// MsgServer is the server API for Msg service.
type MsgServer interface {
	// UpdateParams defines a (governance) operation for updating the module
	// parameters. The authority defaults to the x/gov module account.
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	// SpendFromCommons defines a method for the council to spend funds.
	SpendFromCommons(context.Context, *MsgSpendFromCommons) (*MsgSpendFromCommonsResponse, error)
	// EmergencyCancelGovProposal defines a method for the council to kill a proposal.
	EmergencyCancelGovProposal(context.Context, *MsgEmergencyCancelGovProposal) (*MsgEmergencyCancelGovProposalResponse, error)
	// CreatePolicyPermissions defines the CreatePolicyPermissions RPC.
	CreatePolicyPermissions(context.Context, *MsgCreatePolicyPermissions) (*MsgCreatePolicyPermissionsResponse, error)
	// UpdatePolicyPermissions defines the UpdatePolicyPermissions RPC.
	UpdatePolicyPermissions(context.Context, *MsgUpdatePolicyPermissions) (*MsgUpdatePolicyPermissionsResponse, error)
	// DeletePolicyPermissions defines the DeletePolicyPermissions RPC.
	DeletePolicyPermissions(context.Context, *MsgDeletePolicyPermissions) (*MsgDeletePolicyPermissionsResponse, error)
	// RegisterGroup defines the RegisterGroup RPC.
	RegisterGroup(context.Context, *MsgRegisterGroup) (*MsgRegisterGroupResponse, error)
	// RenewGroup defines the RenewGroup RPC.
	RenewGroup(context.Context, *MsgRenewGroup) (*MsgRenewGroupResponse, error)
	// UpdateGroupMembers defines the UpdateGroupMembers RPC.
	UpdateGroupMembers(context.Context, *MsgUpdateGroupMembers) (*MsgUpdateGroupMembersResponse, error)
	// UpdateGroupConfig defines the UpdateGroupConfig RPC.
	UpdateGroupConfig(context.Context, *MsgUpdateGroupConfig) (*MsgUpdateGroupConfigResponse, error)
	// ForceUpgrade defines the ForceUpgrade RPC.
	ForceUpgrade(context.Context, *MsgForceUpgrade) (*MsgForceUpgradeResponse, error)
	// DeleteGroup defines the DeleteGroup RPC.
	DeleteGroup(context.Context, *MsgDeleteGroup) (*MsgDeleteGroupResponse, error)
	// VetoGroupProposals defines the VetoGroupProposals RPC.
	VetoGroupProposals(context.Context, *MsgVetoGroupProposals) (*MsgVetoGroupProposalsResponse, error)
	// SubmitProposal submits a new proposal to a council for voting.
	SubmitProposal(context.Context, *MsgSubmitProposal) (*MsgSubmitProposalResponse, error)
	// VoteProposal casts a vote on an active proposal.
	VoteProposal(context.Context, *MsgVoteProposal) (*MsgVoteProposalResponse, error)
	// ExecuteProposal executes an accepted proposal.
	ExecuteProposal(context.Context, *MsgExecuteProposal) (*MsgExecuteProposalResponse, error)
	// SubmitAnonymousProposal creates a proposal through the x/shield module.
	// The proposer must be the shield module account (verified by shield ZK proof).
	SubmitAnonymousProposal(context.Context, *MsgSubmitAnonymousProposal) (*MsgSubmitAnonymousProposalResponse, error)
	// AnonymousVoteProposal casts an anonymous vote on a proposal through x/shield.
	// The voter must be the shield module account (verified by shield ZK proof).
	AnonymousVoteProposal(context.Context, *MsgAnonymousVoteProposal) (*MsgAnonymousVoteProposalResponse, error)
	// CreateCategory registers a new shared content category. Restricted to
	// governance or the Commons Council Operations Committee.
	CreateCategory(context.Context, *MsgCreateCategory) (*MsgCreateCategoryResponse, error)
	DeleteCategory(context.Context, *MsgDeleteCategory) (*MsgDeleteCategoryResponse, error)
	// ScheduleRecurringSpend schedules a council-approved recurring
	// disbursement. The signer must be the council policy address (so it is
	// wrapped in a MsgSubmitProposal).
	ScheduleRecurringSpend(context.Context, *MsgScheduleRecurringSpend) (*MsgScheduleRecurringSpendResponse, error)
	// CancelRecurringSpend cancels an active recurring spend schedule. The
	// signer must be the same council policy address that scheduled it,
	// requiring a council proposal.
	CancelRecurringSpend(context.Context, *MsgCancelRecurringSpend) (*MsgCancelRecurringSpendResponse, error)
	// ClaimRecurringSpend disburses one period of an active recurring
	// spend. The signer must be the recipient. Each claim advances the
	// schedule's logical clock by exactly one period.
	ClaimRecurringSpend(context.Context, *MsgClaimRecurringSpend) (*MsgClaimRecurringSpendResponse, error)
	// DeclineRecurringSpend lets the recipient unilaterally opt out of
	// future claims on a schedule (graceful exit when leaving a role). The
	// signer must be the recipient.
	DeclineRecurringSpend(context.Context, *MsgDeclineRecurringSpend) (*MsgDeclineRecurringSpendResponse, error)
}

